const r=await Promise.allSettled([
  tools.exec_command({cmd:"grep -R -n -F 'content.javascript.log_message' qutebrowser tests doc | head -100",workdir:"/app",max_output_tokens:6000}),
  tools.exec_command({cmd:"grep -n -B 4 -A 12 'name: List' qutebrowser/config/configdata.yml | head -120; grep -n -B 5 -A 12 'none_ok: true' qutebrowser/config/configdata.yml | head -180",workdir:"/app",max_output_tokens:8000}),
  tools.exec_command({cmd:"find tests -type f -iname '*config*' | head -80; git status --short",workdir:"/app",max_output_tokens:6000})
]); r.forEach((x,i)=>text(`RESULT ${i+1}: ${x.status==="fulfilled"?x.value.output:String(x.reason)}`));

